    {
      "title": "Defying Death",
      "start_block": "B010",
      "end_block": "B021",
      "hook": "Lady Juliana cuts off Prudence's warnings with fierce conviction: 'The Duchess is dying.'",
      "cliffhanger": "Juliana declares, 'Today, I am only a maid,' accepting a dangerous new identity.",
      "why": "Establishes high stakes (a dying Duchess) and a bold character decision to risk everything, ending on a commitment.",
      "context_gap": "Strangers won't know why saving this specific Duchess matters so much to Juliana."
    }
  ],
